Method.Source:
/// <summary>
/// Class entry point. The system will call this method when a designated menu 
/// is selected or when execution starts and this class is set as the startup class.
/// </summary>
/// <param name = "_args">The specified arguments.</param>
public static void main(Args _args)
{
    GUPPricingAttributeLink GUPPricingAttributeLink;
    ClassId classId = classNum(METGUPPricingAttributeSalesTableAsHeaderSourceMETSalesOrderType);
    ttsbegin;
    delete_from GUPPricingAttributeLink
        where GUPPricingAttributeLink.Source == GUPPricingAttributeSource::SalesLine
           && GUPPricingAttributeLink.FieldName == 'METSalesOrderType'
           && GUPPricingAttributeLink.PriceAttributeClassId != classId;

    update_recordset GUPPricingAttributeLink
        setting PriceAttributeClassId = classId                   
        where GUPPricingAttributeLink.Source == GUPPricingAttributeSource::SalesTable
           && GUPPricingAttributeLink.FieldName == 'METSalesOrderType'
           && GUPPricingAttributeLink.PriceAttributeClassId != classId;
    ttscommit;
    // Old field path is SalesLine#MetItemSiteSettingsSetup_ItemId$ItemId#SubrangeId
    info("@SYS119229");
}
